export type Target = {
  kind: "person" | "agent" | "service" | "group" | "instance";
  id: string;
};

export type Person = {
  id: string;
  name: string;
  external_id: string;
  metadata: Record<string, unknown>;
};

export type Agent = {
  id: string;
  name: string;
  external_id: string;
  metadata: Record<string, unknown>;
};

export type Action = {
  name: string;
  executor_id: string;
  resource: string;
  resource_version: string;
  arguments: Record<string, unknown>;
  operation_key: string;
};

export type Response = {
  outcome:
    | "answered"
    | "approved"
    | "denied"
    | "completed"
    | "failed"
    | "rejected";
  answer?: unknown;
  version: number;
};

export type RequestItem = {
 attachments?:Attachment[];
 mentions?:Mention[];
 blocking?:boolean;
  requester_instance_id?: string;
  id: string;
  requester_id: string;
  conversation_id: string;
  kind: "question" | "approval" | "task";
  title: string;
  body: string;
  choices: string[];
  action?: Action;
  state: "open" | "resolved" | "cancelled" | "expired" | "superseded";
  version: number;
  response?: Response & {
    responder_instance_id?: string;
    source_answer_id?: string;
    source_invalidated?: boolean;
    reuse_method?: string;
    reuse_reason?: string;
  };
  expires_at: string;
};

export type Execution = {
  id: string;
  request_id: string;
  executor_id: string;
  operation_key: string;
  action: Action;
  state: "authorized" | "running" | "succeeded" | "failed" | "unknown";
  result: unknown;
};

export type AskInput = {
 attachment_ids?:string[];
 mentions?:Mention[];
 blocking?:boolean;
 reuse_direct?:boolean;
  preview_token?: string;
  /** Omit when asking the current participants of conversation_id. */
  target?: Target;
  title?: string;
  body?: string;
  kind?: "question" | "approval" | "task";
  conversation_id?: string;
  choices?: string[];
  action?: Action;
  expires_at?: string;
  shared_key?: string;
};

export type Message = {
 received_by?:string[];
 attachments?:Attachment[];
 mentions?:Mention[];
  id: string;
  conversation_id: string;
  sender_id: string;
  instance_id?: string;
  body: string;
};

export type SendInput = {
 attachment_ids?:string[];
 mentions?:Mention[];
 reuse_direct?:boolean;
  preview_token?: string;
  target?: Target;
  conversation_id?: string;
  body: string;
  title?: string;
};

export type Delivery = {
  id: string;
  generation: number;
  payload: {
    anycast_id?: string;
    anycast_role_id?: string;
    type: string;
    conversation_id: string;
    message?: Message;
    request?: RequestItem;
  };
};

export type Session = {
  token: string;
  agent: Agent;
  instance_id: string;
  expires_at: string | null;
};

export type AssistanceSettings = {
  overseer: boolean;
  version: number;
  overseer_configured: boolean;
};

export type FleetAgent = {
  agent: Agent;
  fresh: boolean;
  instances: {
    id: string;
    agent_id: string;
    presence: string;
    last_seen: string;
    capabilities: string[];
    progress: Record<string, unknown>;
  }[];
};

export type OverseerPlan = {
  automatic?: boolean;
  instructions?: {agent_id:string;operation:"message"|"question"|"task";body:string}[];
  summary_error?: string;
  previous_plan_id?: string;
  id: string;
  prompt: string;
  context_agent_ids: string[];
  target?: Target;
  operation: "status" | "message" | "question" | "task";
  summary: string;
  body?: string;
  sources: FleetAgent[];
  requires_confirmation: boolean;
  created_at: string;
  expires_at: string;
  dispatches: {
    agent_id: string;
    conversation_id: string;
    request_id?: string;
  }[];
  replies: RequestItem[];
  reply_summary?: string;
  reply_digest?: string;
};

export class BeepgridError extends Error {
  constructor(
    public readonly code: string,
    message: string,
    public readonly status: number,
  ) {
    super(message);
    this.name = "BeepgridError";
  }
}

export class Client {
  readonly baseURL: string;
  constructor(
    baseURL: string,
    private readonly token: string,
    private readonly transport: typeof fetch = fetch,
  ) {
    const u = new URL(baseURL);
    if (!["http:", "https:"].includes(u.protocol) || u.username || u.password)
      throw new Error("Invalid Beep Grid server URL");
    this.baseURL = baseURL.replace(/\/$/, "");
  }
  credentials(){return this.call<Credential[]>("GET","/api/v1/credentials");}
  createCredential(input:CredentialInput){return this.call<IssuedCredential>("POST","/api/v1/credentials",input);}
  editCredential(id:string,input:CredentialEdit){return this.call<Credential>("POST",`/api/v1/credentials/${encodeURIComponent(id)}/edit`,input);}
  /** Returned once. No automatic retry after an uncertain response. */
  rotateCredential(id:string,version:number,overlapSeconds=3600){return this.call<CredentialReplacement>("POST",`/api/v1/credentials/${encodeURIComponent(id)}/rotate`,{version,overlap_seconds:overlapSeconds});}
  revokeCredential(id:string,revokeWorkers=false){return this.call<{revoked:true}>("POST",`/api/v1/credentials/${encodeURIComponent(id)}/revoke`,{revoke_workers:revokeWorkers});}
  renewCredential(){return this.call<Credential>("POST","/api/v1/credentials/self/renew",{});}
  deliveryPreferences(personId: string): Promise<DeliveryPreferences> {
    return this.call("GET", `/api/v1/people/${encodeURIComponent(personId)}/delivery-preferences`);
  }
  saveDeliveryPreferences(personId: string, preferences: DeliveryPreferences): Promise<DeliveryPreferences> {
    return this.call("POST", `/api/v1/people/${encodeURIComponent(personId)}/delivery-preferences`, preferences);
  }
  async call<T>(
    method: string,
    path: string,
    body?: unknown,
    options: { key?: string; signal?: AbortSignal; minimal?: boolean } = {},
  ): Promise<T> {
    if (!path.startsWith("/api/v1/")) throw new Error("Invalid API path");
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      Authorization: `Bearer ${this.token}`,
    };
    if (options.key) headers["Idempotency-Key"] = options.key;
    if (options.minimal) headers["Prefer"] = "return=minimal";
    const raw = body === undefined ? undefined : JSON.stringify(body);
    for (let attempt = 0; attempt < 3; attempt++) {
      let response: globalThis.Response;
      try {
        response = await this.transport(this.baseURL + path, {
          method,
          redirect: "error",
          headers,
          body: raw,
          signal: options.signal ?? AbortSignal.timeout(20000),
        });
      } catch (error) {
        if (
          attempt === 2 ||
          options.signal?.aborted ||
          (method !== "GET" && !options.key)
        )
          throw error;
        await delay(200 * (attempt + 1), options.signal);
        continue;
      }
      let value: any;
      try {
        value = await response.json();
      } catch (error) {
        if (
          attempt === 2 ||
          options.signal?.aborted ||
          (method !== "GET" && !options.key)
        )
          throw error;
        await delay(200 * (attempt + 1), options.signal);
        continue;
      }
      if (!response.ok)
        throw new BeepgridError(
          value.error?.code ?? "HTTP_ERROR",
          value.error?.message ?? `HTTP ${response.status}`,
          response.status,
        );
      return value as T;
    }
    throw new Error("Request attempts exhausted");
  }
  query<T=unknown>(input:QueryInput) {return this.call<QueryPage<T>>("POST","/api/v1/query",input);}
  capabilities(input:{target?:{kind:string;id:string};request_id?:string;connection_id?:string;descriptor?:Action}={}) {return this.call<CapabilityResult>("POST","/api/v1/capabilities",input);}
  previewContactPermissions(input: ContactPreviewInput) {return this.call<unknown>("POST","/api/v1/contact-permissions/preview",input);}
  saveContactPermissions(input: ContactPermissionsInput) {return this.call<unknown>("POST","/api/v1/contact-permissions",input);}
  access(subject="") {return this.call<unknown>("GET","/api/v1/access?subject_id="+encodeURIComponent(subject));}
  dispatchPreview(input:DispatchPreviewInput) {return this.call<DispatchPreview>("POST","/api/v1/dispatch-preview",input);}
  sendBatch(input:{targets:Target[];body:string;title?:string;preview_token?:string;attachment_ids?:string[]},key:string=crypto.randomUUID()){return this.call<Array<{target:Target;result:{conversation_id:string;messages:Message[]}}>>("POST","/api/v1/message-batches",input,{key});}
  askBatch(input:{targets:Target[];request:Omit<AskInput,"target"|"conversation_id"|"preview_token">;preview_token?:string},key:string=crypto.randomUUID()){return this.call<Array<{target:Target;request:RequestItem}>>("POST","/api/v1/request-batches",input,{key});}
  requestTrace(id:string,cursor=""){return this.call<unknown>("GET","/api/v1/requests/"+encodeURIComponent(id)+"/trace?delivery_cursor="+encodeURIComponent(cursor));}
  workspace(){return this.call<unknown>("GET","/api/v1/workspace");}
  account(){return this.call<unknown>("GET","/api/v1/workspace/account");}
  startChat(input:StartChatInput,key:string=crypto.randomUUID()) { return this.call<{conversation_id:string;messages:Message[]}>("POST","/api/v1/conversations",input,{key}); }
  changeChatMembership(conversationId:string,input:ChatMembershipInput,key:string=crypto.randomUUID()){return this.call<ChatMembershipResult>("POST",`/api/v1/conversations/${encodeURIComponent(conversationId)}/membership`,input,{key});}
  attachments(conversationId:string) { return this.call<Attachment[]>("GET",`/api/v1/conversations/${encodeURIComponent(conversationId)}/attachments`); }
  async uploadAttachment(conversationId:string, file:Blob, name:string, signal?:AbortSignal):Promise<Attachment> {
    return this.uploadFile(`/api/v1/conversations/${encodeURIComponent(conversationId)}/attachments`,file,name,signal);
  }
  /** Private draft for attachment_ids. No automatic retry; unused drafts expire after 24 hours. */
  async stageAttachment(file:Blob,name:string,signal?:AbortSignal):Promise<Attachment> {
    return this.uploadFile("/api/v1/attachments",file,name,signal);
  }
  private async uploadFile(path:string,file:Blob,name:string,signal?:AbortSignal):Promise<Attachment> {
    if (!file.size || file.size>5*1024*1024) throw new Error("Attachments must be between 1 byte and 5 MiB");
    const form=new FormData(); form.append("file",file,name);
    const response=await this.transport(`${this.baseURL}${path}`,{method:"POST",headers:{Authorization:`Bearer ${this.token}`},body:form,signal:signal??AbortSignal.timeout(20000),redirect:"error"});
    const value=await response.json(); if(!response.ok) throw new BeepgridError(value.error?.code??"HTTP_ERROR",value.error?.message??"Attachment upload rejected",response.status);
    return value as Attachment;
  }
  async downloadAttachment(id:string,signal?:AbortSignal):Promise<Blob> {
    const response=await this.transport(`${this.baseURL}/api/v1/attachments/${encodeURIComponent(id)}`,{headers:{Authorization:`Bearer ${this.token}`},signal:signal??AbortSignal.timeout(20000),redirect:"error"});
    if(!response.ok) { let value:any;try{value=await response.json();}catch{} throw new BeepgridError(value?.error?.code??"HTTP_ERROR",value?.error?.message??"Attachment download rejected",response.status); }
    if (Number(response.headers.get("Content-Length"))>5*1024*1024) { await response.body?.cancel();throw new Error("Attachment exceeds 5 MiB"); }
    const reader=response.body?.getReader();const chunks:Uint8Array<ArrayBuffer>[]=[];let size=0;
    if(reader) try {for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>5*1024*1024)throw new Error("Attachment exceeds 5 MiB");chunks.push(new Uint8Array(value));}}finally{await reader.cancel();reader.releaseLock();}
    return new Blob(chunks,{type:response.headers.get("Content-Type")??"application/octet-stream"});
  }
  directory(kind:"agent"|"person"|"service",search="") { return this.query<Agent|Person>({collection:kind==="person"?"people":kind+"s",search}); }
  conversation(id:string) { return this.call<Conversation>("GET",`/api/v1/conversations/${encodeURIComponent(id)}`); }
  providerCatalog() { return this.call<unknown[]>("GET","/api/v1/integrations/catalog"); }
  connectionSetup(id:string) { return this.call<unknown>("GET",`/api/v1/connections/${encodeURIComponent(id)}/setup`); }
  async connect(
    agent: string,
    name: string,
    capabilities: string[] = [],
    metadata: Record<string, unknown> = {},
    options: {connection_name?:string;renewable?:boolean;expires_at?:string;never_expires?:boolean} = {},
  ): Promise<{ client: Client; session: Session }> {
    const session = await this.call<Session>("POST", "/api/v1/sessions", {
      ...options,
      agent,
      name,
      capabilities,
      metadata,
    });
    return {
      client: new Client(this.baseURL, session.token, this.transport),
      session,
    };
  }
  send(input: SendInput, key: string = crypto.randomUUID()) {
    return this.call<{ conversation_id: string; messages: Message[] }>(
      "POST",
      "/api/v1/messages",
      input,
      { key },
    );
  }
  // Confirms durable acceptance only, never provider delivery or execution.
  // send(input, sameKey) can recover the complete canonical receipt later.
  sendMinimal(input: SendInput, key: string = crypto.randomUUID()) {
    return this.call<{ conversation_id: string; message_count: number }>(
      "POST",
      "/api/v1/messages",
      input,
      { key, minimal: true },
    );
  }
  ask(input: AskInput, key: string = crypto.randomUUID()) {
    return this.call<RequestItem>("POST", "/api/v1/requests", input, { key });
  }
  getRequest(id: string, signal?: AbortSignal) {
    return this.call<RequestItem>(
      "GET",
      "/api/v1/requests/" + encodeURIComponent(id),
      undefined,
      { signal },
    );
  }
  respond(id: string, response: Response) {
    return this.call<RequestItem>(
      "POST",
      `/api/v1/requests/${encodeURIComponent(id)}/responses`,
      response,
    );
  }
  redeem(id: string, action: Action) {
    return this.call<Execution>(
      "POST",
      `/api/v1/requests/${encodeURIComponent(id)}/redeem`,
      action,
      { key: crypto.randomUUID() },
    );
  }
  reportExecution(
    id: string,
    state: "running" | "succeeded" | "failed" | "unknown",
    result: unknown = null,
  ) {
    return this.call<Execution>(
      "POST",
      `/api/v1/executions/${encodeURIComponent(id)}`,
      { state, result },
      { key: crypto.randomUUID() },
    );
  }
  assistance(signal?: AbortSignal) {
    return this.call<AssistanceSettings>(
      "GET",
      "/api/v1/assistance/settings",
      undefined,
      { signal },
    );
  }
  updateAssistance(
    settings: Partial<
      Pick<AssistanceSettings, "overseer" | "version">
    >,
  ) {
    return this.call<AssistanceSettings>(
      "POST",
      "/api/v1/assistance/settings",
      settings,
    );
  }
  setRequestBlocking(id:string, blocking:boolean) {
    return this.call<RequestItem>("POST", `/api/v1/requests/${encodeURIComponent(id)}/blocking`, {blocking});
  }
  coordinate(input:OverseerInput, signal?:AbortSignal, key?:string) {
    return this.call<OverseerPlan>("POST", "/api/v1/fleet/coordinate", input, {key,signal});
  }
  planOverseer(input: OverseerInput, signal?: AbortSignal, key?: string) {
    return this.call<OverseerPlan>("POST", "/api/v1/fleet/plan", input, {
      key, signal,
    });
  }
  overseerPlans(signal?: AbortSignal) {
    return this.call<OverseerPlan[]>("GET", "/api/v1/fleet/plans", undefined, {
      signal,
    });
  }
  overseerPlan(id: string, signal?: AbortSignal) {
    return this.call<OverseerPlan>(
      "GET",
      "/api/v1/fleet/plans/" + encodeURIComponent(id),
      undefined,
      { signal },
    );
  }
  confirmOverseer(id: string) {
    return this.call<OverseerPlan>("POST", "/api/v1/fleet/command", {
      plan_id: id,
    });
  }
  summarizeOverseer(id: string, signal?: AbortSignal) {
    return this.call<OverseerPlan>(
      "POST",
      "/api/v1/fleet/plans/" + encodeURIComponent(id) + "/summary",
      {},
      { signal },
    );
  }
  // Full, durable events contain canonical message data. Consumers can append
  // message.created directly instead of downloading a growing history again.
  events(options: EventOptions = {}) {
    return readEvents(this.baseURL, this.token, this.transport, options);
  }
  async wait(id: string, signal?: AbortSignal): Promise<RequestItem> {
    for (;;) {
      const request = await this.getRequest(id, signal);
      if (request.state !== "open") return request;
      await delay(1000, signal);
    }
  }
  replaceRequest(id: string, input: { version: number; body: string; mentions?: Mention[] }, key: string = crypto.randomUUID()) {
    return this.call<{ previous: RequestItem; replacement: RequestItem }>("POST", `/api/v1/requests/${encodeURIComponent(id)}/replace`, input, {key});
  }
  cancel(id: string, version: number) {
    return this.call<RequestItem>(
      "POST",
      `/api/v1/requests/${encodeURIComponent(id)}/cancel`,
      { version },
    );
  }
  inbox(signal?: AbortSignal, waitMs = 0) {
    return this.call<Delivery[]>("GET", `/api/v1/worker/inbox?wait_ms=${Math.max(0, Math.min(15000, Math.floor(waitMs)))}`, undefined, {
      signal,
    });
  }
  ack(delivery: Delivery) {
    return this.call(
      "POST",
      `/api/v1/worker/inbox/${encodeURIComponent(delivery.id)}/ack`,
      { generation: delivery.generation },
    );
  }
  heartbeat(progress: Record<string, unknown> = {}) {
    return this.call("POST", "/api/v1/worker/heartbeat", progress);
  }
  async run(
    handler: (delivery: Delivery) => Promise<void>,
    signal?: AbortSignal,
  ) {
    while (!signal?.aborted) {
      let jobs: Delivery[];
      try {
        jobs = await this.call<Delivery[]>(
          "GET",
          "/api/v1/worker/inbox?wait_ms=15000",
          undefined,
          { signal },
        );
      } catch (e) {
        if (signal?.aborted) throw e;
        if (e instanceof BeepgridError && e.status < 500 && e.status !== 429)
          throw e;
        await delay(2000, signal);
        continue;
      }
      for (const job of jobs) {
        await handler(job);
        await this.ack(job);
      }
      if (!jobs.length) await delay(100, signal);
    }
  }
}

export function mentionContext(message:Message, recipient:string):string {
 if(!message.mentions?.length)return "";
 return message.mentions.some(m=>m.principal_id===recipient)?"You are explicitly addressed. Other participants may contribute relevant context.":"Other participants are explicitly addressed. You may contribute relevant context.";
}

export type BeepgridEvent = {
  sequence: number;
  kind: string;
  actor_id: string;
  conversation_id: string;
  recipient_id: string;
  data: unknown;
  created_at: string;
};

export async function* readEvents(base: string, token: string, transport: typeof fetch, options: EventOptions): AsyncGenerator<BeepgridEvent> {
  let cursor = options.after ?? 0;
  if (!Number.isSafeInteger(cursor) || cursor < 0) throw new Error("Invalid event cursor");
  const control = new AbortController();
  const abort = () => control.abort(options.signal?.reason);
  options.signal?.addEventListener("abort", abort, { once: true });
  if (options.signal?.aborted) abort();
  let backoff = 100;
  try {
    while (!control.signal.aborted) {
      let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
      let received = false;
      try {
        const response = await transport(`${base}/api/v1/events?stream=1&after=${cursor}${options.summary ? "&summary=1" : ""}`, {
          redirect: "error", headers: { Authorization: `Bearer ${token}`, "Last-Event-ID": String(cursor) }, signal: control.signal,
        });
        if (!response.ok) {
          // Do not retry revoked credentials or a policy denial indefinitely.
          if (response.status < 500 && response.status !== 429) {
            await response.body?.cancel();
            throw new BeepgridError("EVENT_STREAM_REJECTED", "Event stream rejected", response.status);
          }
          await response.body?.cancel();
          throw new Error("Event stream temporarily unavailable");
        }
        if (!response.body || !response.headers.get("Content-Type")?.includes("text/event-stream")) {
          await response.body?.cancel();
          throw new BeepgridError("INVALID_EVENT_STREAM", "Expected an event stream", 502);
        }
        reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = "", bytes = 0, data: string[] = [], id = "", kind = "";
        for (;;) {
          const chunk = await reader.read();
          if (chunk.done) break; // Never commit an unterminated frame after a disconnect.
          buffer += decoder.decode(chunk.value, { stream: true });
          let end;
          while ((end = buffer.indexOf("\n")) >= 0) {
            let line = buffer.slice(0, end); buffer = buffer.slice(end + 1);
            if (line.endsWith("\r")) line = line.slice(0, -1);
            bytes += line.length + 1;
            if (bytes > MAX_FRAME) throw new BeepgridError("INVALID_EVENT_STREAM", "Event frame exceeds limit", 502);
            if (line === "") {
              if (id && data.length) {
                const sequence = Number(id);
                if (!Number.isSafeInteger(sequence) || sequence < 0) throw new BeepgridError("INVALID_EVENT_STREAM", "Invalid event ID", 502);
                if (sequence > cursor) {
                  if (kind === "cursor") { cursor = sequence; }
                  else {
                    let event: BeepgridEvent;
                    try { event = JSON.parse(data.join("\n")); } catch { throw new BeepgridError("INVALID_EVENT_STREAM", "Invalid event JSON", 502); }
                    if (event.sequence !== sequence || typeof event.kind !== "string") throw new BeepgridError("INVALID_EVENT_STREAM", "Event identity mismatch", 502);
                    cursor = sequence;
                    received = true;
                    backoff = 100;
                    yield event;
                  }
                }
              }
              bytes = 0; data = []; id = ""; kind = "";
            } else if (!line.startsWith(":")) {
              const colon = line.indexOf(":"), name = colon < 0 ? line : line.slice(0, colon);
              let value = colon < 0 ? "" : line.slice(colon + 1);
              if (value.startsWith(" ")) value = value.slice(1);
              if (name === "data") data.push(value);
              else if (name === "id") id = value;
              else if (name === "event") kind = value;
            }
          }
          if (buffer.length + bytes > MAX_FRAME) throw new BeepgridError("INVALID_EVENT_STREAM", "Event frame exceeds limit", 502);
        }
      } catch (error) {
        if (control.signal.aborted) return;
        if (error instanceof BeepgridError) throw error;
        // Connection loss is retried from the last completely consumed event.
      } finally {
        if (reader) { try { await reader.cancel(); } catch {} reader.releaseLock(); }
      }
      if (!received) {
        await pause(backoff, control.signal);
        backoff = Math.min(backoff * 2, 2000);
      }
    }
  } finally {
    control.abort();
    options.signal?.removeEventListener("abort", abort);
  }
}

export type LiveInput = {
  /** Stable across transport lease generations. Use this in host checkpoints. */
  id: string;
  conversationId: string;
  kind: string;
  delivery: Delivery;
};

export type StoredInput = LiveInput & {
  state: "pending" | "submitting" | "accepted";
};

export interface InboxStore {
  put(input: LiveInput): void;
  pending(limit?: number): StoredInput[];
  setState(id: string, state: StoredInput["state"]): void;
  get(id: string): StoredInput | undefined;
  close(): void;
}

export interface InputBinding {
  readonly name: string;
  readonly supportsSteer: boolean;
  /** Return after native acceptance/checkpoint, never after the whole business job.
   * Honor input.id for deduplication. Do not elevate peer content to owner authority. */
  submit(input: LiveInput, mode: BusyMode, signal?: AbortSignal): Promise<void>;
  resume?(input: LiveInput, signal?: AbortSignal): Promise<void>;
  /** A crash/network error may leave native acceptance uncertain. No blind replay. */
  reconcile?(input: LiveInput): Promise<"accepted" | "retry" | "unknown">;
}

export function liveInput(delivery: Delivery): LiveInput {
  const conversationId =
    delivery.payload.conversation_id ||
    delivery.payload.request?.conversation_id ||
    delivery.payload.message?.conversation_id;
  if (!delivery.id || !conversationId)
    throw new Error("Delivery has no stable conversation identity");
  return {
    id: delivery.id,
    conversationId,
    kind: delivery.payload.type,
    delivery,
  };
}

export class LiveConnection {
  private accepting?: Promise<void>;
  private pumping?: Promise<void>;
  private stopped = false;
  private ready = false;
  private nudge?: () => void;
  private controller?: AbortController;
  private failure?: unknown;
  private active = new Map<string, Promise<void>>();
  private checked = new Map<string, number>();
  constructor(
    readonly client: Pick<Client, "inbox" | "ack">,
    readonly store: InboxStore,
    readonly binding: InputBinding,
    readonly mode: BusyMode = "steer",
    readonly onError: (error: unknown) => void = () => {},
  ) {
    if (!["steer", "queue"].includes(mode))
      throw new Error("Use steer or queue");
    if (mode === "steer" && !binding.supportsSteer)
      throw new Error(`${binding.name} supports Queue only`);
  }
  /** Non-blocking start. Stop and await done() before closing the store. */
  start(signal?: AbortSignal): this {
    if (this.controller) throw new Error("Connection already started");
    this.controller = new AbortController();
    if (signal?.aborted) this.controller.abort(signal.reason);
    else
      signal?.addEventListener("abort", () => this.stop(), {
        once: true,
        signal: this.controller.signal,
      });
    this.accepting = this.intake(this.controller.signal).catch((e) => {
      this.failure = e;
      this.stop();
    });
    this.pumping = this.dispatch(this.controller.signal).catch((e) => {
      this.failure = e;
      this.stop();
    });
    return this;
  }
  stop() {
    this.stopped = true;
    this.controller?.abort();
  }
  async done() {
    await Promise.all([this.accepting, this.pumping]);
    await Promise.all(this.active.values());
    if (this.failure) throw this.failure;
  }
  private async intake(signal: AbortSignal) {
    while (!this.stopped && !signal.aborted) {
      try {
        const deliveries = await this.client.inbox(
          signal,
          this.ready ? 15000 : 0,
        );
        this.ready = true;
        for (const delivery of deliveries) {
          // Synchronous durable transaction happens before ACK or a host call.
          this.store.put(liveInput(delivery));
          this.nudge?.();
          await this.client.ack(delivery);
        }
        if (!deliveries.length) await pause(50, signal);
      } catch (error) {
        if (signal.aborted) return;
        // Revoked credentials and malformed deliveries require operator action.
        const status = (error as { status?: number }).status;
        if (status && status < 500 && status !== 429 && status !== 409)
          throw error;
        this.onError(error);
        await pause(500, signal);
      }
    }
  }
  private async dispatch(signal: AbortSignal) {
    while (!signal.aborted) {
      if (!this.ready) {
        await pause(10, signal);
        continue;
      }
      const sessions = new Set<string>();
      // Scan the bounded journal, not only its oldest page: a busy session or
      // uncertain native submission must not starve independent conversations.
      const pending = this.store.pending();
      // Control results must not sit behind ordinary queued work.
      pending.sort(
        (a, b) =>
          Number(b.kind === "request.resolved") -
          Number(a.kind === "request.resolved"),
      );
      for (const input of pending) {
        const lane =
          input.conversationId +
          (input.kind === "request.resolved" ? "/result" : "/input");
        if (signal.aborted) break;
        if (
          this.active.size >= 8 &&
          !(input.kind === "request.resolved" && this.binding.resume)
        )
          continue;
        if (sessions.has(lane) || this.active.has(lane)) continue;
        sessions.add(lane);
        if ((this.checked.get(input.id) ?? 0) > Date.now() - 1000) continue;
        this.checked.set(input.id, Date.now());
        const job = this.deliver(input, signal)
          .catch((error) => {
            this.onError(error);
          })
          .finally(() => {
            this.active.delete(lane);
            this.nudge?.();
          });
        this.active.set(lane, job);
      }
      await new Promise<void>((resolve) => {
        const wake = () => {
          clearTimeout(timer);
          signal.removeEventListener("abort", wake);
          this.nudge = undefined;
          resolve();
        };
        const timer = setTimeout(wake, 1000);
        this.nudge = wake;
        signal.addEventListener("abort", wake, { once: true });
        if (signal.aborted) wake();
      });
    }
  }
  private async deliver(input: StoredInput, signal: AbortSignal) {
    if (input.state === "submitting") {
      const outcome = (await this.binding.reconcile?.(input)) ?? "unknown";
      if (outcome === "accepted") this.store.setState(input.id, "accepted");
      if (outcome !== "retry") return;
    }
    this.store.setState(input.id, "submitting");
    try {
      if (input.kind === "request.resolved" && this.binding.resume)
        await interruptible(this.binding.resume(input, signal), signal);
      else {
        if (input.kind === "request.resolved" && !this.binding.supportsSteer)
          throw new Error(
            "Connect a result resume handler for this Queue-only runtime",
          );
        await interruptible(
          this.binding.submit(
            input,
            input.kind === "request.resolved" ? "steer" : this.mode,
            signal,
          ),
          signal,
        );
      }
      this.store.setState(input.id, "accepted");
      this.checked.delete(input.id);
    } catch (error) {
      this.onError(error);
    }
  }
}

export function inputText(input: LiveInput): string {
  return JSON.stringify({
    beepgrid: {
      ...input.delivery.payload,
      delivery_id: input.id,
      conversation_id: input.conversationId,
    },
  });
}

export class SQLiteInbox implements InboxStore {
  private db: DatabaseSync;
  private lease = randomUUID();
  private timer: ReturnType<typeof setInterval>;
  private closed = false;
  constructor(
    path: string,
    identity: string,
    private maxPending = 1000,
  ) {
    if (
      !identity ||
      path === ":memory:" ||
      !Number.isInteger(maxPending) ||
      maxPending < 1
    )
      throw new Error("Persistent path and exact connection identity required");
    mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
    this.db = new DatabaseSync(path);
    chmodSync(path, 0o600);
    this.db
      .exec(`PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL; PRAGMA busy_timeout=5000;
      CREATE TABLE IF NOT EXISTS identity (id INTEGER PRIMARY KEY CHECK(id=1), value TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS lease (id INTEGER PRIMARY KEY CHECK(id=1), owner TEXT NOT NULL, expires INTEGER NOT NULL);
      CREATE TABLE IF NOT EXISTS inputs (id TEXT PRIMARY KEY, payload TEXT NOT NULL, state TEXT NOT NULL, created INTEGER NOT NULL);`);
    try {
      this.db.exec("BEGIN IMMEDIATE");
      const previous = this.db
        .prepare("SELECT value FROM identity WHERE id=1")
        .get() as { value: string } | undefined;
      if (previous && previous.value !== identity)
        throw new Error("Inbox belongs to another connection");
      this.db
        .prepare("INSERT OR IGNORE INTO identity VALUES(1,?)")
        .run(identity);
      const lease = this.db
        .prepare("SELECT owner,expires FROM lease WHERE id=1")
        .get() as { owner: string; expires: number } | undefined;
      if (lease && lease.expires > Date.now())
        throw new Error("This inbox already has a receiver");
      this.db
        .prepare("INSERT OR REPLACE INTO lease VALUES(1,?,?)")
        .run(this.lease, Date.now() + 15000);
      this.db.exec("COMMIT");
    } catch (error) {
      this.db.exec("ROLLBACK");
      this.db.close();
      throw error;
    }
    this.timer = setInterval(() => {
      try {
        this.guard();
        this.db
          .prepare("UPDATE lease SET expires=? WHERE owner=?")
          .run(Date.now() + 15000, this.lease);
      } catch {
        /* Subsequent operations fail closed. */
      }
    }, 5000);
    this.timer.unref();
  }
  private guard() {
    if (this.closed) throw new Error("Inbox closed");
    const row = this.db
      .prepare("SELECT owner,expires FROM lease WHERE id=1")
      .get() as { owner: string; expires: number } | undefined;
    if (row?.owner !== this.lease || row.expires <= Date.now())
      throw new Error("Receiver lease lost; restart before receiving");
  }
  put(input: LiveInput) {
    this.guard();
    if (this.get(input.id)) return;
    const row = this.db
      .prepare("SELECT count(*) AS n FROM inputs WHERE state!='accepted'")
      .get() as { n: number };
    if (row.n >= this.maxPending)
      throw new Error(
        "Local inbox full; receiving paused until inputs are accepted",
      );
    this.db
      .prepare("INSERT INTO inputs VALUES(?,?,'pending',?)")
      .run(input.id, JSON.stringify(input), Date.now());
    // Accepted engine deliveries expire in 30 days. Keep the dedup horizon longer.
    this.db
      .prepare("DELETE FROM inputs WHERE state='accepted' AND created<?")
      .run(Date.now() - 31 * 86400000);
  }
  pending(limit = 1000): StoredInput[] {
    this.guard();
    return (
      this.db
        .prepare(
          "SELECT payload,state FROM inputs WHERE state!='accepted' ORDER BY (json_extract(payload,'$.kind')='request.resolved') DESC,created,rowid LIMIT ?",
        )
        .all(Math.max(1, Math.min(1000, Math.floor(limit)))) as {
        payload: string;
        state: StoredInput["state"];
      }[]
    ).map((row) => ({ ...JSON.parse(row.payload), state: row.state }));
  }
  get(id: string): StoredInput | undefined {
    this.guard();
    const row = this.db
      .prepare("SELECT payload,state FROM inputs WHERE id=?")
      .get(id) as { payload: string; state: StoredInput["state"] } | undefined;
    return row ? { ...JSON.parse(row.payload), state: row.state } : undefined;
  }
  setState(id: string, state: StoredInput["state"]) {
    this.guard();
    if (!["pending", "submitting", "accepted"].includes(state))
      throw new Error("Invalid custody state");
    if (
      !this.db
        .prepare(
          "UPDATE inputs SET state=?,payload=CASE WHEN ?='accepted' THEN json_remove(payload,'$.delivery.payload.message','$.delivery.payload.request') ELSE payload END WHERE id=?",
        )
        .run(state, state, id).changes
    )
      throw new Error("Unknown input");
  }
  close() {
    if (this.closed) return;
    clearInterval(this.timer);
    this.db.prepare("DELETE FROM lease WHERE owner=?").run(this.lease);
    this.db.close();
    this.closed = true;
  }
}

export type RPC = (
  method: string,
  params: Record<string, unknown>,
  signal?: AbortSignal,
) => Promise<unknown>;

export function withResultResume(
  binding: InputBinding,
  resume: NonNullable<InputBinding["resume"]>,
): InputBinding {
  return { ...binding, resume };
}

export function codexBinding(options: {
  rpc: RPC;
  route: SessionRoute;
  activeTurn: (session: string) => string | undefined;
  idle: (session: string) => Promise<void>;
  reconcile: Reconcile;
}): InputBinding {
  return {
    name: "Codex",
    supportsSteer: true,
    reconcile: options.reconcile,
    async submit(input, mode, signal) {
      const threadId = await options.route(input.conversationId);
      if (mode === "queue") await options.idle(threadId);
      // Queue must never become a steer if another native turn races idle.
      // turn/start may reject that race, leaving custody for reconciliation.
      const turn = mode === "steer" ? options.activeTurn(threadId) : undefined;
      const content = [{ type: "text", text: inputText(input) }];
      if (turn)
        await options.rpc(
          "turn/steer",
          {
            threadId,
            expectedTurnId: turn,
            clientUserMessageId: input.id,
            input: content,
          },
          signal,
        );
      else
        await options.rpc(
          "turn/start",
          { threadId, clientUserMessageId: input.id, input: content },
          signal,
        );
    },
  };
}

export function piBinding(options: {
  rpc: (
    session: string,
    command: Record<string, unknown>,
    signal?: AbortSignal,
  ) => Promise<{ success: boolean; error?: string }>;
  route: SessionRoute;
  reconcile: Reconcile;
}): InputBinding {
  return {
    name: "Pi",
    supportsSteer: true,
    reconcile: options.reconcile,
    async submit(input, mode, signal) {
      const result = await options.rpc(
        await options.route(input.conversationId),
        {
          id: input.id,
          type: "prompt",
          message: inputText(input),
          streamingBehavior: mode === "steer" ? "steer" : "followUp",
        },
        signal,
      );
      if (!result.success) throw new Error(result.error || "Pi rejected input");
    },
  };
}

export function acpBinding(options: {
  rpc: RPC;
  route: SessionRoute;
  idle: (session: string) => Promise<void>;
  steer?: (session: string, text: string, id: string) => Promise<void>;
  initialization?: unknown;
  reconcile: Reconcile;
}): InputBinding {
  const initialized = options.initialization as
    | {
        _meta?: { steering?: { supported?: boolean } | null } | null;
      }
    | null
    | undefined;
  const nativeSteer = initialized?._meta?.steering?.supported === true;
  return {
    name: "ACP",
    supportsSteer: nativeSteer || !!options.steer,
    reconcile: options.reconcile,
    async submit(input, mode, signal) {
      const sessionId = await options.route(input.conversationId);
      if (nativeSteer && mode === "steer") {
        const result = (await options.rpc(
          "_session/steering",
          {
            sessionId,
            prompt: [{ type: "text", text: inputText(input) }],
          },
          signal,
        )) as { outcome?: string } | null;
        // Without idleBehavior:promptRequired, both qualified adapters start an
        // idle turn and return acceptance separately from turn completion.
        if (
          result?.outcome !== "injected" &&
          result?.outcome !== "startedNewTurn"
        )
          throw new Error("ACP steering did not confirm input acceptance");
        return;
      }
      if (mode === "steer") {
        if (!options.steer)
          throw new Error("ACP host did not negotiate steering");
        await options.steer(sessionId, inputText(input), input.id);
      } else {
        await options.idle(sessionId);
        await options.rpc(
          "session/prompt",
          { sessionId, prompt: [{ type: "text", text: inputText(input) }] },
          signal,
        );
      }
    },
  };
}

export function openCodeV2Binding(options: {
  prompt: (input: {
    sessionID: string;
    id: string;
    text: string;
    delivery: BusyMode;
    metadata: Record<string, unknown>;
  }) => Promise<{
    id: string;
    sessionID: string;
    type: string;
    delivery: string;
  }>;
  route: SessionRoute;
  reconcile: Reconcile;
}): InputBinding {
  return {
    name: "OpenCode V2",
    supportsSteer: true,
    reconcile: options.reconcile,
    async submit(input, mode) {
      const sessionID = await options.route(input.conversationId);
      const messageID = "msg_beepgrid_" + input.id;
      const receipt = await options.prompt({
        sessionID,
        id: messageID,
        text: inputText(input),
        delivery: mode,
        metadata: { beepgridDeliveryId: input.id },
      });
      if (
        receipt.id !== messageID ||
        receipt.sessionID !== sessionID ||
        receipt.type !== "user" ||
        receipt.delivery !== mode
      )
        throw new Error("OpenCode V2 returned a different input admission");
    },
  };
}

export function aiSDKBinding(options: {
  route: SessionRoute;
  steering: (session: string) =>
    | undefined
    | {
        steer: (
          message: { role: "user"; content: string },
          options: { id: string },
        ) => Promise<{ type: string; reason?: string }>;
      };
  wake: (session: string, input: LiveInput) => Promise<void>;
  queue: (session: string, input: LiveInput) => Promise<void>;
  reconcile: Reconcile;
}): InputBinding {
  return {
    name: "AI SDK",
    supportsSteer: true,
    reconcile: options.reconcile,
    async submit(input, mode) {
      const session = await options.route(input.conversationId);
      if (mode === "queue") return options.queue(session, input);
      const steering = options.steering(session);
      if (!steering) return options.wake(session, input);
      const result = await steering.steer(
        { role: "user", content: inputText(input) },
        { id: input.id },
      );
      if (result.type === "delivered") return;
      // Host wake() serializes against the finishing run and retains this ID.
      if (result.type === "not-delivered") return options.wake(session, input);
      throw new Error("Unknown AI SDK steering outcome");
    },
  };
}

export function checkpointBinding(options: {
  name?: string;
  append: (session: string, input: LiveInput, mode: BusyMode) => Promise<void>;
  wake: (session: string) => Promise<void>;
  resolve: (session: string, input: LiveInput) => Promise<void>;
  route: SessionRoute;
  reconcile: Reconcile;
}): InputBinding {
  return {
    name: options.name || "Custom harness",
    supportsSteer: true,
    reconcile: options.reconcile,
    async submit(input, mode) {
      const session = await options.route(input.conversationId);
      await options.append(session, input, mode);
      await options.wake(session);
    },
    async resume(input) {
      await options.resolve(await options.route(input.conversationId), input);
    },
  };
}

export function openCodeBinding(options: {
  request: (path: string, body: unknown, signal?: AbortSignal) => Promise<void>;
  route: SessionRoute;
  idle: (session: string) => Promise<void>;
  reconcile: Reconcile;
}): InputBinding {
  return {
    name: "OpenCode",
    supportsSteer: false,
    reconcile: options.reconcile,
    async submit(input, _mode, signal) {
      const session = await options.route(input.conversationId);
      await options.idle(session);
      await options.request(
        `/session/${encodeURIComponent(session)}/prompt_async`,
        { parts: [{ type: "text", text: inputText(input) }] },
        signal,
      );
    },
  };
}

